export const SUN_LECTURES: Record<string, string> = {
  'Aries': `En la relación de pareja eres alegre, fuerte e independiente, eres una persona atrevida y apasionada y te gusta decidir por los dos. Vives en el presente, con entusiasmo, liderazgo, valentía, velocidad y dinamismo. Pero también puedes caer en el egoísmo, la arrogancia, la  impulsividad y el egocentrismo. Puedes ser inconstante, intolerante, impaciente, brusco o demasiado competitiv@.`,
  'Tauro': `En la pareja eres leal, constante y posesiva. Tienes un espíritu artístico, valoras la belleza, el lujo y la sensualidad. Eres confiable, paciente y práctica. Sin embargo, puedes caer en la terquedad, ser argumentativa y necia. Tu posesividad se puede convertir en problema, así como el materialismo y la avaricia.`,
  'Géminis': `Eres sociable, inteligente y divertida, así como también adaptable, curiosa y expresiva. Eres interesante y muy comunicativa. Pero puedes ser cambiante, inconstante o distraída. Te gusta el chisme y la intriga. Cuidado con la mentira, las trampas o la falta de agradecimiento.`,
  'Cáncer': `Eres emotiva, compasiva y doméstica. Tu naturaleza sensible te hace intuitiva, precavida y administrada. A veces ser demasiado emocional te hace ser autocompasiva, hipersensible, sentirte víctima o ser temerosa. Apoyas a quienes amas, pero evita ser sobreprotectora porque puede convertirse en control o manipulación.`,
  'Leo': `Eres romántica, apasionada, cariñosa, te enamoras apasionadamente y lo das todo. Tienes un espíritu generoso, artístico y optimista. Eres digna y segura de ti mismo. Sin embargo, puedes ser vanidosa, orgullosa o dramática. También puedes caer en la arrogancia, el derroche o demasiado dominante.`,
  'Virgo': `Eres detallista, servicial y leal. Tu naturaleza solidaria, prudente y objetiva te hace una excelente pareja, estarás pendiente de todo lo que tu pareja necesite. Pero cuidado de perder la dignidad, ser demasiado fría, criticona o juzgar premeditadamente.`,
  'Libra': `Eres una pareja amable, bella y cooperativa. Eres afectuosa, sociable y armoniosa. Te entregas completamente y buscas compartir todo con tu pareja. Sin embargo, puedes llegar a dejar toda decisión en sus manos, ser demasiado complaciente, quejarte y solo esperar a que él cambie. Tiendes a ser insegura y dependiente de tu pareja. Tienes un espíritu pacifico y artístico pero también puedes ser inconstante o apática.`,
  'Escorpio': `Eres intuitiva, observadora, inteligente y determinada. Sabes obtener lo que deseas. Eres apasionada y sincera. La intensidad de tus emociones te puede hacer temperamental, hiriente e incluso rencorosa. Cuidado con los celos y la lujuria.`,
  'Sagitario': `Eres una pareja alegre, franca y entusiasta. Disfrutas de tu libertad, evitas lo emocional y prefieres abordar la relación con un espíritu filosófico basado en lo que es justo. Eres optimista, naturalmente tienes la vista hacia el futuro y solo te sientes completo cuando la relación tiene un propósito que te emociona. A pesar de tu generosidad, puedes ser imprudente o argumentativo, tus ideales pueden hacer difícil ver la perspectiva de la otra persona. Y puedes tender a la irresponsabilidad, impaciencia o exageración lo que te hace difícil mantener un compromiso a largo plazo.`,
  'Capricornio': `Eres una pareja seria, responsable y tradicional. Valoras lo material, eres práctica y ambiciosa. Puedes aparentar frialdad pero es por tu naturaleza cauta y prudente. Por otro lado, puedes actuar de forma dominante y egoísta. Cuidado también con no ser demasiado negativa, pues tiendes a sobrevalorar el pasado. Si bien es importante guiar tus acciones hacia aquello que te genere admiración, recuerda que no solo vivimos para otras personas y es importante escucharte a ti mismo y a tu pareja.`,
  'Acuario': `Eres inteligente e independiente. Valoras tu libertad e individualidad. Prefieres la lógica sobre las emociones. Tampoco eres la pareja más paciente, puedes ser intolerante si no comparten tu inteligencia. Eres autentica y original pero también puedes ser impredecible, o incluso rebelde. Ante todo, cuida la soberbia. Te es más fácil mantener una relación basada en la amistad, que en el romance.`,
  'Piscis': `Eres intuitiva, emotiva y comprensiva. También soñadora, a veces fantasiosa. Tienes un lado artístico, espiritual, incluso místico. Eres muy romántica y soñadora. También puedes ser muy sensible, volverte pesimista o sentirte incomprendida. Eres distraída, tímida y a veces hasta floja por lo que te costará avanzar la relación por ti misma. Eres caritativa, pero a veces das de más, lo que termina haciéndote sentir como víctima.`
};

export const MOON_LECTURES: Record<string, string> = {
  'Aries': `Buscas alegría, emoción y actividad. No toleras el aburrimiento. Necesitas vivir en el presente y sentirte independiente. Eres emocionalmente fuerte y prefieres la competencia a la dependencia. Puedes ser impulsiv@ y tender al enojo. También caer en el egoísmo, te cuesta trabajo considerar las emociones de tu pareja.`,
  'Tauro': `Buscas lealtad, estabilidad, y comodidad. Tus necesidades emocionales parten de la seguridad y estabilidad financiera. Requieres belleza, lujo y placer para tu estabilidad. No toleras la deslealtad. Eres paciente, pero si se termina reaccionas con enojo. Puedes ser obstinada y argumentativa.`,
  'Géminis': `Tiendes a buscar la diversión, lo interesante y saciar tu curiosidad. Necesitas hablar de tus emociones. También ser sociable y escuchar los chismes e intrigas de los demás. Eres inteligente y adaptable pero ocasionalmente puedes reaccionar con desinterés y evasión. Preferirás utilizar una mentira a tener una confrontación emocional.`,
  'Cáncer': `Eres muy emocional y buscas seguridad y protección. Necesitas tiempo para conectar con tus emociones, en especial en el hogar y rodeada del amor de tu familia. La seguridad financiera también es importante para no sentirte vulnerable. Tus emociones pueden ser demasiado complejas para tu pareja. Tu buena memoria te hace recordar situaciones previas que otras personas olvidan. Es importante que cuides tus cambios de ánimo pues pueden ser abrumadores.`,
  'Leo': `Ante todo buscas el amor, de forma romántica y apasionada. Tu seguridad emocional parte de quien eres y como te ven los demás. Eres orgullosa, y necesitas sentirte amada y admirada por otros. Tu vanidad también requiere verte bien para sentirte bien. Cuidado con ser demasiado explosiva y dramática. Tus relaciones son intensas y puedes ser extenuante para tu pareja. Eres amorosa pero a veces puedes actuar con arrogancia, sentirte superior a tu pareja e incluso actuar cruelmente.`,
  'Virgo': `Buscas el orden, la limpieza y la salud. Eres metódica y objetiva necesitas sentir control para tu estabilidad emocional. El servicio calma tu naturaleza nerviosa, así como el trabajo mental que requiere atención al detalle. Tener un plan ante los imprevistos te hace sentir tranquila. Cuida de no reaccionar emocionalmente con prejuicio e incluso hipocresía. Eres analítica lo que a veces te hace actuar con frialdad y menospreciar las emociones de los demás.`,
  'Libra': `Buscas la paz, armonía y tranquilidad. Tus necesidades emocionales empiezan por los sentidos. Necesitas un entorno que consideres agradable. Tus relaciones son lo más importante y necesitas que sean justas y que puedas depender de ellas. Cuando no encuentras la armonía, tiendes a quejarte. Rara vez resuelves los problemas por ti misma y la soledad es lo que más te afecta.`,
  'Escorpio': `Tienes emociones intensas y profundas. Eres intuitiva, sabes lo que otras personas sienten y piensan. Pero eres reservada con tus emociones y puedes guardar rencores. Cuidado porque a quien más le afecta es a ti. Necesitas tiempo de soledad, para recuperar tu fortaleza y aclarar tus pensamientos. Atraes lo que deseas, pero si tus deseos no son puros te puede traer problemas. En especial si tu temperamento y celos se vuelven autodestructivos. Pero es justo ante la dificultad que encuentras la fuerza interna para renacer.`,
  'Sagitario': `Tus emociones predominantes son la alegría, optimismo y libertad. No te gusta sentirte atrapada, necesitas espacio, tiempo al aire libre y metas que te entusiasmes para sentirte emocionalmente satisfecha. A veces eres imprudente, en especial si tu pareja es muy sensible. Puedes exagerar las situaciones, y prefieres evitar hablar sobre tus emociones, a veces utilizando el sarcasmo. En lugar de eso, abordas la vida con un espíritu filosófico basado en tus ideales. Tus emociones dependen más del futuro que del presente.`,
  'Capricornio': `No eres muy emocional. Tiendes a ser cauta, seria e incluso fría. Para ti la seguridad material es más importante. Tu reputación es también muy importante, te esfuerzas por ser bien vista y causar admiración. Encuentras tranquilidad en lo convencional, no te gusta experimentar nuevas cosas, y prefieres aquello que es práctico. Ante las dificultades, puedes reaccionar con negatividad. Tu ambición también te puede hacer actuar con egoísmo y utilizar a las personas para el cumplimiento de tus objetivos.`,
  'Acuario': `Tus emociones las abordas desde la lógica, no desde el corazón. Incluso te pueden resultar incómodas, sobre todo cuando otras personas las demuestran profusamente. Puedes incluso actuar con intolerancia y frialdad ante genuinas muestras de vulnerabilidad de tu pareja. Eso no significa que no tengas necesidades emocionales, tu libertad es lo más importante. Si te sientes atrapada o no puedes ser tú misma es cuando más temperamental te vuelves. También es importante el estímulo intelectual y ser reconocida por lo que sabes. Solo cuida no actuar con soberbia.`,
  'Piscis': `Vives tus emociones a flor de piel. Eres muy sensible e intuitiva. Pero si no tienes cuidado puedes caer en la tristeza. Eres soñadora, pero cuida de no ilusionarte demasiado. Necesitas desarrollar fortaleza emocional o terminarás sintiéndote como víctima. En lugar de abrumarte enfócate en desarrollar tu intuición, será tu mejor guía para navegar un mundo lleno de sorpresas, y bendiciones. También asegúrate de desarrollar tu fe, te dará fuerza para enfrentar y equilibrar tu predisposición a la negatividad. A pesar de tu emocionalidad, puedes actuar con timidez y reprimir tus emociones con tu pareja. Procura no hacerlo pues solo te hará sentir mas incomhendida. Mejor compártele tu ilusión y sueños y quien sabe, tal vez se pueden hacer realidad.`
};

export const VENUS_LECTURES: Record<string, string> = {
  'Aries': `Tu felicidad radica en la actividad, emoción e independencia. Expresas cariño con alegría y de forma rápida e impulsiva. Tu amor nace de la competencia, necesitas admirar la fortaleza e independencia de tu pareja. Tu inestabilidad y necesidad de libertad puede afectar la relación. Tu independencia puede hacer sentir a tu pareja sola, que no puede depender de ti o que eres egoísta. Tu pareja ideal será aquella que sea fuerte, valiente e independiente con la que pueda divertirte y realizar actividades variadas.`,
  'Tauro': `Tu felicidad está en el lujo, la belleza y el placer. Expresas cariño con sensualidad. La lealtad y fidelidad es lo más importante en tu relación. Pero en exceso se puede convertir en celos y posesividad. Tu relación también puede ser afectada si actúas con necedad o pasividad. Pero en general, eres confiable, paciente y hogareña. Tu pareja favorita ideal aquella persona fuerte, firme y tranquila, que tenga buenos valores y en la que puedas confiar.`,
  'Géminis': `Tu felicidad está en las relaciones sociales, lo interesante, y la inteligencia. Expresas cariño de forma divertida e inventiva. Puedes decir cosas muy bonitas y sentir genuina curiosidad por tu pareja. Necesitas admirar su inteligencia. Puedes ser muy cambiante y la mentira es lo que mas afecta tu relación. Buena comunicación es esencial en tu relación. Tu inquietud puede causar malentendidos. Tu pareja ideal será aquellas persona inteligente, interesante y divertida con la que puedas conversar, pasear y socializar.`,
  'Cáncer': `Venus en Cáncer disfruta del hogar, la familia y la comida. Tiendes a la timidez y prefieres expresar el amor en lo privado, que en público. Buscas dar y recibir protección. La seguridad financiera es importante en tu relación. Habrá veces que sientas mucho amor y otras poco. Puedes apegarte de mucho al pasado y ser demasiado tradicional o conservadora.Tu personas favoritas serán aquellas que sean sensibles, hogareñas y con grandes valores familiares con quien sientas seguridad, cariño y contención.`,
  'Leo': `Para ti la felicidad está en el amor, el romance y la pasión. Lo material es importante y expresas tu cariño con grandes gestos románticos. Tienes magnetismo y puedes despertar envidia en otros, ser deseada es una forma de hacer sentir orgullo a tu pareja. Sin embargo, eres sorprendentemente honesta y fiel: tu pareja puede confiar en ti. Puedes tener expectativas demasiado altas para tu pareja. Exiges ser el centro de atención y puedes actuar de forma dramática y poco comprensiva. Tu orgullo es delicado, aparentas seguridad pero te sientes herida fácilmente.Tu pareja ideal serán aquellas que tenga belleza y porte, que te admire, te haga brillar, te complazca en todo pero que tenga seguridad en sí misma.`,
  'Virgo': `Tu felicidad esta en el orden, la limpieza y la salud. Demuestras amor con los detalles. Eres entregada, solidaria y servicial. No eres emocionalmente muy expresiva pero le demuestras a tu pareja tu amor con tu lealtad. A veces eres fría y el contacto físico te incomoda. La limpieza es importante, tanto en ti como en tu pareja. Puedes ser quisquillosa y darle demasiada importancia a cosas pequeñas. También ser demasiado crítica con tu pareja, es importante que actúes con objetividad y evitar la hipocresía. Tu pareja ideal será aquella que se fije en los detalles, que sea ordenado and saludable, que tome en cuenta lo que es importante para ti, te ayude y te apoye de manera natural.`,
  'Libra': `Tu felicidad está en tu relación de pareja, la armonía y cooperación. Expresas tu cariño afectuosamente. Eres persuasiva y buscas soluciones que sean justas y armoniosas. Eres refinada, buscas la belleza, el arte y la creatividad. Tu mayor problema es la dependencia. Tiendes a la inconstancia e inseguridad lo que hace difícil encontrar balance si tu pareja no es fuerte y confiable. Eres sociable y agradable pero si las cosas no salen como quieres puedes ser quejumbrosa, inconstante o incluso floja. Te es difícil resolver problemas por ti misma. Tu pareja ideal será aquella que sea fuerte y te de seguridad, que te tome en cuenta para prácticamente todo, que sea cariñoso, amable y detallista.`,
  'Escorpio': `Tu felicidad se centra en el cumplimiento de tus deseos. Buscas la intensidad emocional, aun si viene acompañada de celos y emociones tóxicas. Demuestras tu amor con sensualidad, a veces en exceso. Eres inteligente, observadora e intuitiva conoces a tu pareja con profundidad, incluso más de lo que es se conoce el mismo. Sin embargo, te puede hacer controladora, manipuladora y actuar con arrogancia. La intensidad de tu amor llega a causar inestabilidad en la pareja. Cuando todo está bien las cosas son maravillosas, pero cuando no, pueden ser incluso peligrosas. Por tu bien, procura no guardar rencores y ser vengativa. Mejor enfoca tu poder de atracción en buenas intenciones. Tu pareja ideal será aquella persona apasionada e inteligente, que tenga carácter y buenos valores, que sepa lo que quiere y lo consiga, que sea sincera y no se deje engañar.`,
  'Sagitario': `Tu felicidad esta en tu libertad, los viajes o actividades al aire y lo brillante que pueda parecer el futuro. Expresas tu cariño con alegría y generosidad, pero rara vez de forma emocional. Por tu naturaleza optimista tiendes a tomar riesgos, disfrutas de lo emocionante y puede ser difícil para tu pareja compartir tu amor al riesgo, y cuando no seas muy responsable, le puede ser difícil saber que puede confiar en ti. Tu constante búsqueda de libertad puede crear distanciamiento. Cuidado con ser demasiado argumentativa, o evadir situaciones difíciles con sarcasmo. Eres una persona divertida pero también hay momentos que hay que tomar las cosas con seriedad. Tu pareja ideal será aquella que sle guste la aventura, viajar y divertirse, que te haga sentir libre y que sea muy dinámico e independiente, que sea inteligente y desee convertirse en una persona más sabia.`,
  'Capricornio': `Tu felicidad está centrada en el éxito y la admiración de los demás. No expresas tu amor efusivamente, en lugar de eso eres alguien responsable, que disfruta de proveer y causar que tu pareja sienta orgullo de quien eres. Puedes ser perfeccionista, y enfocarte en lo material. Para tu pareja puede ser difícil no poder alcanzar un vínculo emocional. Tiendes a guiarte por lo tradicional, y tu relación se basará más en lo que piensen otras personas que en tus emociones. Para tu pareja también puede ser difícil adaptarse a tu pragmatismo e incluso egoísmo. Tienes metas muy claras y en ocasiones las priorizas sobre tu relación de pareja. Cuidado con ser demasiado negativa, recuerda que la vida también es para disfrutar.`,
  'Acuario': `Tu felicidad está en la amistad, libertad y sabiduría. No toleras la ignorancia. Demuestras tu cariño a tu pareja como si fueran amigos: respetando su espacio, escuchando sin juzgar y sin caer en excesiva emocionalidad. Tu pareja no es alguien convencional. Admiras su originalidad, e incluso excentricidad. Te gusta porque te permite ser tu misma y respeta tu libertad. Eres rebelde y no encuentras la felicidad dependiendo de otra persona. Admiras la inteligencia y amas ante todo la sabiduría de tu pareja. A pesar de tu frialdad, tienes un espíritu humano y altruista. Das sin esperar recibir nada a cambio. Tu pareja ideal será aquella que sea inteligente e interesante, con quien sientas confianza y libertad, que puedas expresarte de forma sincera y auténtica y que comprenda y respete la importancia que tienen tus amistades.`,
  'Piscis': `Tu felicidad está en transmitir y alcanzar tus sueños. Si logras superar tus miedos y melancolía vivirás una vida mágica, llena de misterio y emotiva. Eres tímida al expresar tu amor, pero cuando lo haces te entregas por completo. Eres sensible, tus emociones son tan complejas que pueden ser difícil para tu pareja entenderlas. También eres intuitiva, tu pareja no te puede esconder las cosas. Tus fantasías pueden hacer que te engañes a ti misma. La música es indispensable para sanar tu alma. Vívela y disfruta al máximo. Trata de perseguir el arte, aun algo simple como el dibujo, te servirá para expresarte y sentirte comprendida. Ante todo, busca y ama a Dios, tal como tu espiritualidad te lo permita. Solo en místico encontrarás el consuelo que en este mundo no encuentras. Tu pareja ideal será aquella que sea cariñoso y atento, que te trate con delicadeza. Que te de seguridad y contención, que tenga paciencia y, aunque a veces no te comprenda, te respete. Que tenga buen corazón y valores espirituales.`
};

export const CASA_SOLAR_LECTURES: Record<string, string> = {
  'Casa I': `Eres una mujer voluntariosa, con una personalidad radiante y que con tu sola apariencia atraes atención. Tu presencia ilumina el lugar en donde estas, y las demas personas admiran tu actitud ante la vida. Vienes a compartir esa luz para hacer cada momento presente especial. Ser la líder y encaminar a otros con tu luz, voluntad y guia.`,
  'Casa II': `Tu felicidad nace a partir de la posesiones materiales y seguridad económica. Sabes apreciar naturalmente el valor de las cosas. Disfrutar de tener y generar dinero. Lo que no resulta obvio para otros es que el exito financiero es el reflejo de tus valores y autovaloración. La seguridad, propiedades y dinero son los mecanismos para construir pero solo perdura aquello que tiene buenos valores, como los cimientos de un edificio. Recuerda que en esta vida, todo es prestado y solo lo mantenemos si lo cuidamos, y le damos buen uso. Otras personas admiran tu abundancia y estás aquí para enseñar y compartir tus recursos pero siempre basada en tus valores y la capacidad de generar mas. Por que así como en la lealtad, tu felicidad esta en que te regresen mas de lo que diste.`,
  'Casa III': `Brillas con tu palabra, con tu elocuencia, comunicas e inteligencia. Eres feliz cuando platicas con muchas personas todos los días. Cuando en tu vida diaria hay variedad, diversidad e intriga. Tu felicidad esta en aquello que te da curiosidad, te parece intersante o divertido. Admiras la inteligencia, necesitas estar bien informada y te gusta estudiar pero no con profundidad, prefieres saber poco de muchos temas distintos. Las relaciones sociales, en especial con tus hermanos, también son muy importantes para tu felicidad.`,
  'Casa IV': `Tu mayor felicidad se encuentra en el hogar y la familia. Brillas cuando te sientes segura, rodeada de las personas que amas y te sientes en confianza de compartir tus emociones. Amas la buena comida y disfrutar los alimentos en compañía de tu familia. Eres la líder en el hogar, quien mantiene a la familia unida y quien sabe como repartir las responsabilidades para mantener un hogar feliz. Eres altamente emocional y brillas mas cuando puedes regular y compartir tus emociones. También tienes un amor inmenso para dar y sobresale cuando puedes cuidar y nutrir a otros. Aún cuando puedas ser apegada y sobre protectora, tu mayor recompensa es ver el crecimiento de otros, apreciar los frutos de tu amor, cuidado y atención otros crecen. Para brillar, busca a quien cuidar y mantener un jardín o mascotas te dara gran satisfacción.`,
  'Casa V': `Tu felicidad nace a partir de tu creatividad. Necesitas sentir pasión, romance incluso un poco de drama para sentirte feliz, sentirte completa, para brillar. Cuando estás bien, las personas admiran tu deseo de vivir, como puedes convertir cada momento en un momento especial y como tienes tantos talentos que te convierten en el centro de atención a donde vayas. Tu pareja es afortunada, aun con el drama al que tiendes, tu brillo le hace sentir envidiado y quizá algo celoso, lo que ayuda mantener el romance y la pasión en la relación. Solo recuerda no exigir tanto como lo que das, eres bendecida en tener tanta luz, eso es un don, otros no pueden dar a brillar como tu y eso esta bien.`,
  'Casa VI': `Tu felicidad nace a partir de tu salud. De la calidad de tu vida diaria, de tus hábitos, de tu capacidad de controlar tu realidad. De la limpieza y orden del entorno en el que estas. Y del valor del servicio que ofreces a partir de tu trabajo. Brillas cuando sirves a otros, cuando dejas atras tu ego y con tu solidaridad y atención mejoras la vida de otras personas. Aprenderas que Dios te regresa con creces lo que haces por los demás. Cuando estas bien, otras personas admiran tu abnegación, tu humildad, tu disposición de servir y el orden de tu vida. Tu felicidad no está detrás de grandes gestos, esta en la tranquilidad de que todo esta bajo control ya que has cumplido con tu deber.`,
  'Casa VII': `La mayor satisfacción de tu vida se encuentra en tu pareja. Eres una mujer que naturally sabe compartir, pero también balancear la relacion para que sea “justa”. Brillas cuando haces las cosas junto a tu pareja, te sientes completa, acompañada y sacas lo mejor de cada uno. Lo mismo ocurre con las sociedades. Cuando estas bien, las otras personas admiran tu relacion de pareja la felicidad, luz y estabilidad que demuestran. Esta bien convertirte en la “líder” de la relacion. Guiar a tu pareja y la relacion en base a tu luz interior. Pero recuerda que es muy posible que la relacion sea mas importante para tu felicidad que para la de tu pareja. Esta bien de vez en cuando dar un poco de mas.`,
  'Casa VIII': `Tu felicidad nace de tu interior. Disfrutas de tus momentos de soledad. En general, eres introvertida y necesitas tiempo de soledad para reconectar contigo y recargar tu fuerza. Es en esos momentos cuanda alcanzas la claridad e intuicion que te guían para salir adelante. Tus emociones te son muy importantes y profundas, aun si las compartes y eres reservada. Pocas personas tienen la introspección para revelar los misterios, secretos e intenciones que tenemos en nuestro interior y en el de los demas. Detrás de toda la superficialidad de facetas que mostramos al mundo, se encuentran nuestros deseos y tienes el don de volverlos realidad tanto para ti como para otros.`,
  'Casa IX': `Tu felicidad muy lejos de la cotidianidad y aburrimiento de la vida diaria, y en wsu lugar se encuentra en la persecución de las grandes aspiraciones. Buscas la grandeza, lo extraordinario aquello que es perfecto y muy superior a la mediocridad y experiencias promedio cotideanas. Tienes el don de la vision, a encontrar la verdad donde otros no la ven. A encontrar la grandeza aun cuando parece lejano o inalcanzable. Y a aspirar a aquel ideal que otros ni siquiera pueden entender. Tu felicidad esta en aspirar. Los viajes, el estudio de la filosofía, ciencia o espiritualidad o todo aquello que te saque de de la frivolidad cotidanea es tu camino a la grandeza.`,
  'Casa X': `Tu mayor felicidad esta en alcanzar el éxito, el honor y prestigio social. Brillas cuando estas en posiciones de liderazgo, cuando adquieres mucha responsabilidad y otros dependen de ti para triunfar. La opinion de los demas te es muy importante, disfrutas de su admiración y por lo mismo debes ser escrupulosa y cuidar mucho de la moralidad tus acciones. El éxito y prestigio que tanto anhelas lo encontraras a través de tu desarrollo profesional. En base al trabajo, esfuerzo y el cumplimiento de tu palabra y responsabilidades. Conforme avances, tendrás la oportunidad de liderear a otros y es la admiración y positiva opinion de quien diriges la que te dará mayor felicidad. Con el éxito, llegara prosperidad y abundancia material. Si bien es correcto disfrutarlas, solo recuerda el porque haces las cosas y que lo mas importante para ti es es que otros puedan confiar en ti.`,
  'Casa XI': `Brillas cuando trabajas en grupo. Cuando te entregas a una causa . La camaradería, solidaridad y amistad llenan tu ser de felicidad. No hay mayor recompensa que lograr algo “importante” que parecía imposible y que jamás se hubiera logrado individualmente. Trabajar hacia una causa te permite olvidarte de ti, de los problemas, de las relaciones, incluso del sentimiento de insignificancia o impotencia que rige nuestra vida diaria. Lo mas importante es que sientes que perteneces a algo, sientes que has encontrado tu lugar, que has encontrado personas como y curas ese sentimiento de soledad, de sentirte diferente o incomprendida. Y lo mejor de todo es que con el trabajo del grupo se beneficia el bien común. Quizá no se note en un principio, pero con el tiempo los frutos de tu trabajo son vivir en una mejor sociedad, donde haya mas camaradería, mas fraternidad, mas comprensión e incluso un poco mas de libertad.`,
  'Casa XII': `Encontrarás la felicidad cuando encuentres tu espiritualidad. Cuando te encuentres sin fe, el mundo no hará sentido, sera demasiado intimidante, existirá demasiado sufrimiento. Pero son esos momentos de impotencia, de derrota que te hacen alzar la vista en busqueda de comprensión. De entender el propósito de tanto dolor, y de recobrar tu fe para redescubrir tu voluntad de servicio. Eres valiente, no cualquiera soporta la carga que tienes, la conciencia, la sensibilidad, el silencio que oculta al miedo y dolor. Pero es precisamente por lo que Dios te ha elegido, porque eres fuerte, eres gloriosa y eres la encargada a cumplir su obra. A brindar protección a quien sufre, esperanza al desahuciado y FE a quien no tiene ojos para ver la inmortalidad del espíritu y la grandeza de Dios. Amén.`
};

export const CASA_KARMA_LECTURES: Record<string, string> = {
  'Casa I': `En esta vida, vienes a aprender a compartir, a que para recibir también hay que dar.Tienes la tendencia karmica a actuar de forma egoísta, a solo considerar tus necesidades y a no pensar en los demas. Sobre todo con tu pareja. A madurar, a dejar atras esa actitud ante la vida infantil de solo buscar recibir y comenzar a pensar en los demas. Sobretodo en tu pareja. A desarrollar esa conciencia de “nosotros” que requiere de sacrificar deseos personales para alcanzar metas en pareja. A disminuir tu ego, que te impide apreciar las circunstancias desde la perspectiva de la otra persona. Y encontrar el balance que le permita a tu relacion ser “justa” en donde recibes tanto como cuanto das.`,
  'Casa II': `Tienes la tendencia karmica a sobrevalorar el dinero y buscar seguridad en las posesiones materiales. Como resultado tus valores se han deteriorado y careces de funadamentos para guiar tus acciones. En esta vida, vienes a reconectar con tu yo interior, a buscar en la soledad y las profundidades de tu subsconsciente el poder que te brindara esa seguridad que estas buscando. Aprenderás a renacer y encontrar la capacidad de manifestar a partir de tu interior, no en las cosas materiales. El tiempo en soledad te obseqauiara intuición, y comenzaras a valorarte no por lo que tienes sino por tus valores.`,
  'Casa III': `Tienes la tendencia karmica a buscar grandes aspiraciones. Pero a menospreciar la superficialidad de la vida diaria y las relaciones sociales. Actuas en base a lo que ves, pero no lo comunicas. Por lo que aun si actúas en base a la verdad o el ideal que buscas, no puedes trasladarlo a la vida diaria. Tienes el don de ver la Verdad, ahora vienes aprender a comunicarla. En esta vida, vienes a desarrollar relaciones, a escuchar verdades o ideales distintas de la tuya, y aprender a compartir tu verdad de forma interesante, persuasiva y divertida. Tus hermanos y vecinos son relaciones especialmente importantes porque aunque las puedes evitar, no las puedes ignorar por completo. Y porque las grandes transformaciones inician desde nuestro entorno mas cercano.`,
  'Casa IV': `Tienes la tendencia karmica a depender de la familia. En vidas pasadas, preferiste la seguridad del hogar que cumplir tus responsabilidades en el mundo real. En esta vida vienes a alcanzar el éxito progresivamente , responsabilidades y status social. Pasarás de depender a permitir que otros dependan de ti. Has venido en esta vida a brillar bajo la luz pública. Tener cargos y responsabilidades en donde te conviertas en la líder y adquieras comodidad bajo la escrupulosa mirada de otros. El éxito no te será fácil y tu profesión se vuelve un aspecto muy importante de tu desarrollo personal. Aún si te gustaría quedarte en casa, la necesidad de tu misma familia te empujara a salir al mundo exterior y adquirir responsabilidades. Tu palabra y compromiso se vuelven lo mas valioso que tienes y deberás cuidar mucho tu imagen publica, porque la responsabilidad y el éxito te traerán HONOR pero también envidia y enemigos.`,
  'Casa V': `Tienes la tendencia karmica a buscar la diversion, el romance y el goce. En esta vida vienes a entregarte a causas mas importantes que trascienden tu bienestar personal. Vienes a construir el bien común. A mirar mas alla de tu beneficio personal y a trabajar en grupo por causas que beneficien colectivamente a la sociedad en la que vivimos. Has sido una buena madre, dedicado tu atención y amor al cuidado de los hijos. Pero en esta vida te toca aprender que, en ocasiones, lo mejor que podemos hacer por las personas que amamos es construir un mejor futuro. Dejar atras el drama, la busqueda de romance y pasión y comenzar a pensar de forma objetiva lo que todos necesitamos, no solo lo que tu quieres. Tienes grandes capacidades: creatividad, pasión y entrega ahora te toca ponerlas al servicio para el beneficio de otros y en el proceso encontrar la felicidad y sentimiento de pertenencia que buscas.`,
  'Casa VI': `Tienes la tendencia karmica a enfocarte de mas en el mundo material. En la cotidianidad de la rutina diaria, en la salud, en los hábitos, en el trabajo. Pero en esta vida has venido a aprender que hay mucho mas de lo que podemos ver o sentir. En esta vida has sido elegida para redescubrir el mundo espiritual, nuestra fuente, el lugar de donde originalmente venimos, lo que se preserva aun cuando toda la materia perece. Encontras que hay enfermedades que ni el medico mas poderoso puede curar, pero Dios las desaparece mágicamente, instantaneamte. Que de alguna forma la verdad no esta en lo que nuestros ven, que la eternidad no esta en lo material, que la fe es la entrada al camino espiritual en donde se encuentra tu verdadera vocación. Has sido elegida para una vida de serivicio, para una vida de entrega, para sanar a quien sufre, para alegrar a quien tiene tristeza y para compartir la buena noticia a quien no tiene esperanza. Felicidades!`,
  'Casa VII': `Tienes la tendencia karmica a dar de más, a priorizar las necesidades de los otros sobre las tuyas y a depender de tu pareja. En esta vida vienes a desarrollar tu voluntad, a cultivar un ego sano para balancear la relacion de pareja. Vienes a transformar tu actitud ante la vida arraigada en tus tendencias karmicas y a renacer con una nueva personalidad y apariencia ante el mundo.`,
  'Casa VIII': `Tienes la tendencia karmica a experimentar profundas transformaciones. Sabes que el verdadero valor proviene de uno mismo, disfrutas de los momentos de soledad y tienes mucha intuicion pero te ha costado manifestar ese poder interior en el mundo material. En esta vida vienes a materializar tus valores, a dejar atras los constantes cambios y alcanzar estabilidad. Aprenderás a valor las posesiones y apreciar la seguridad que te traen. Desarrollarás tu sistema de valores tal que no solo sean conscientes para ti, sino también para los demas. Como resultado de tu crecimiento material, alcanzaras riqueza y prosperidad pero solo siempre y cuando estén alineados a los valores de tu yo interior.`,
  'Casa IX': `Tienes la tendencia karmica a diluirte en la superficialidad de las relaciones sociales cotideanas. En lugar de eso, en esta vida vienes a buscar grandes aspiraciones. A alejarte del chisme, falsedad y frivolidad del diario vivir, y a encontrar una aspiración que le de propósito a tu vida. Los viajes, la filosofía, el estudio e incluso religion y política son el camino para encontrar esa verdad o ideal que le dará sentido a tu vida.`,
  'Casa X': `Tienes la tendencia karmica a buscar honor y status social pero a costa de la felicidad de otros. En vidas pasadas, has estado en posiciones de liderazgo pero lo has malutilizado, siendo demasiado autoritaria o dominante. En esta vida, te toca dejar atras el honor personal y nutrir el éxito de tu familia. Te tocara remplazar el trabajo por comprensión, responsabilidad por compresión, el trabajo por sensibilidad y éxito por amor. Entenderás que la opinion mas importante no es la de la sociedad sino de las personas que amamos. Que nuestro poder de creación, no es a través del trabajo sino de la familia. Y que el verdadero triunfo no es al alcanzar liderazgo y reconociendo sino al propiciar un hogar en donde todos puedas crecer, cada uno a su forma y ritmo. Si continuas buscando el éxito exterior las necesidades familiares te harán tomar decisiones difíciles.`,
  'Casa XI': `En esta vida has venido a encontrar la felicidad, el gozo, y romance. Vienes a cultivar tu desarrollar tu creatividad empezando por los hijos, a nutrir con amor, atención y lentamente con el tiempo apreciar como todo lo que diste se regresa con creces. Vienes de vidas anteriores, en donde te has ocupado demasiado de “grandes” problemas en sacrificio de tu felicidad personal. Quizá tus intenciones fueron buenas, pero tus acciones se volvieron demasiado radicales. En esta vida debes evitar obsesionarte por temas que aunque son importantes, poco puedes cambiar. Paradójicamente has venido a aprender humildad, pero a través del desarrollo del ego. De esa conciencia personal de donde creatividad nace que aunque limitada es inmensamente poderosa para procurarnos una vida feliz.`,
  'Casa XII': `Tienes la tendencia karmica a sumergirte en las profundidades emocionales sin prestar atención al mundo material. Has vivido vidas pasadas de mucho sufrimiento, pero también mucha fe. Has alcanzado la espiritualidad, al entender que la materia perece y lo único que perdura es el espíritu. Pero ahora, vienes a alejarte de ese abismo sin fin que es las profundidades del espíritu y a reencontrarte con Dios en su creación. A dejar atras la busqueda de brindar esperanza al desahuciado y entregar tu misericordioso espíritu, a mejorar las condiciones materiales de quienes lo necesitan. Vienes a cultivar un templo para la maxima realización del espíritu. Para ser conducto de la voluntad Divina, para cuidar su creación. Vienes a adquirir hábitos de limpieza, salud, trabajo y organización para traer a nuestro imperfecto mundo material la magnanimidad de Dios, nuestro creador.`
};

export const VALORES_INTRO_LECTURE = `El propósito de la pareja es desarrollar nuestra capacidad de amar. El amor es una fuerza que nos hace lograr lo imposible. Aquello que jamás imaginamos posible, aquello que rompe nuestras creencias y limitaciones. El amor puede sacar a la luz la mejor persona que podemos ser, pero también destruirnos. Para que el amor se sostenga y prevalezca debe estar basado en los valores correctos. Conforme desarrollamos nuestra capacidad de amar, también vamos descubriendo nuestros valores. Los valores son la capa de nuestro inconsciente más profunda y nos guía en la toma de decisiones. Los valores son más profundos incluso que nuestras creencias, nuestras limitaciones, las opiniones de los demás y nuestros deseos. Los valores trazan los límites que no podemos rebasar sin consecuencias negativas. Lo que el amor busca es alinear nuestras creencias y limitaciones con nuestros valores. El amor empuja esas barreras imaginarias de nuestro subconsciente para encontrar nuestros verdaderos límites y expandir nuestra capacidad creadora que proviene de nuestra capacidad de amar.`;

export const VALORES_LECTURES: Record<string, string> = {
  'Aries': `Los desafíos que enfrentas en tu relación de pareja te ayudan a desarrollar tu amor propio y dignidad. A través de las dificultades encontrarás tu fuerza y descubrirás que tan capaz eres para triunfar sin depender de otros. De la misma forma, descubrirás tus límites de dar a otros, no porque no puedas dar más, sino porque va en contra de tu dignidad. Tu sabes quien eres, cuanto vales, que mereces y que quieres. Tu amor propio no te permitirá rebasar esos límites que favorezcan a otros en detrimento de ti. Encontrarás que esa fuerza que te hace lograr cosas imposibles solo puede ser dirigida si nace a partir de tu amor propio, no para otras personas. Eso no es algo malo. Al contrario, tienes mucho que enseñar a otros que no tengan el sentimiento de dignidad tan fortalecido. El amor que sentimos es la forma de comunicarse de Dios con nosotros, con nuestro corazón. Aprenderás a escuchar ese amor propio y actuar acordemente, no te preocupes de actuar de forma impulsiva o buscar resultados rápidos. Sabes mejor que nadie, que lo que es para ti, fácil lo obtendrás, y si no es mejor seguir adelante. Eso sí, en ocasiones tendrás que actuar con valentía, sobre todo cuando otros no la tengan. Pero lo harás porque es lo que mereces. De tu amor, nace tu capacidad de liderazgo.`,
  'Tauro': `Los desafíos que enfrentas en la pareja son para desarrollar tu sentimiento de lealtad. Aprenderás que el amor es lo más valioso que tenemos y no lo podemos entregar a quien no nos corresponde. Encontrarás que en diferentes circunstancias podrás actuar de forma muy diferente, que se podría juzgar como ilógica, o injusta. Pero lo haces porque eres leal. Cuando eres correspondida actúas con paciencia, fuerza estabilidad y le haces saber a tu pareja que puede confiar en ti. Pero cuando no eres correspondida, actuarás firme, intolerante, casi iracunda. También podrás  ser juzgada por tu amor a las cosas materiales, pero no es que seas materialista (aunque puedes serlo). Es que aprecias el esfuerzo y trabajo que cuesta conseguirlas, saber decir que NO, aun cuando queremos algo, o cuando otros te piden los frutos por los que has trabajado tanto. Pero sobre todo, tu apego a las posesiones materiales nace del sentimiento de seguridad que aportan porque sabes cuanto vales, lo hermosa que eres, y sensible también. Sabes que las circunstancias y relaciones son frágiles, y las posesiones, bienes materiales y propiedades te dan la estabilidad que mereces y necesitas. Tiendes a actuar con celos, que está bien, es correcto proteger lo que es tuyo, y trazar límites firmes de lo que estás dispuesta a tolerar. Solo recuerda enfocar tus celos basados en la lealtad, no ganaras nada defendiendo a quien no te corresponde y quien no te valora tanto como tu.`,
  'Géminis': `Los desafios que enfrentas en tu relación de pareja son para desarrollar tu capacidad de comunicarte. Y sobre todo de comunicarte con amor. Mejor que nadie, entenderás que muchos problemas se originan en la falta de comunicación. En los malentendidos, chismes, rumores, pero también en las mentiras. En la medida que priorices el amor al momento de escuchar y de hablar encontrarán soluciones. Quizá no siempre te gusten los resultados, en ocasiones tendrás que adaptarte, otras cambiar pero con el tiempo entenderás que nuestra palabra es nuestra herramienta de creación. Comunicarte con amor te dará lugar a una vida hermosa, armoniosa, que disfrutes. Comunicarte con intriga, mentiras o ingratitud dará lugar a una vida falsa, intrigante, inestable y sin alegría. Aprenderás que comunicarte con amor, no solo cambia nuestro alrededor sino también a la persona que amas. Que la claridad, honestidad, empatía y comprensión crean una relación estable. La evasión, incertidumbre y falta de atención causan resentimiento y separación. Pero sobre todo aprenderás y enseñarás que tanto la vida como el amor no son serios e inflexibles, sino divertidos, interesantes y fluidos como el cauce de un río. A través de tu palabra, despertaras con la curiosidad y asombro de no saber que pasara hoy, pero sentir que será extraordinario. Cada día es un regalo.`,
  'Cáncer': `Los desafíos que enfrentas en tu relación te mostraran lo grande que es tu capacidad de proteger. Por las personas que amas, lograrás rebasar límites que trascienden tus creencias basadas en los valores que recibiste y las opiniones de los demás y la sociedad. Descubrirás que el verdadero valor de tu amor no es a quien se lo entregas, eso trasciende tu entendimiento o poder de decisión. En su lugar, los frutos de tu amor son ver el crecimiento de tu la pareja y familia a quien te entregas nutridos por tu amor, y protección. La compasión, comprensión e intuición basada en tu voluble híper sensibilidad te guiará para actuar de formas que nunca imaginaste posible. Sin embargo, tu forma de amar deberá ser balanceada entre la delicada línea de nutrir y prever. Entenderás que el amor incondicional no solo depende del presente, sino del pasado y del futuro. Tu intuición se nutrirá de tu privilegeda memoria para que actúes maternalmente. Amar, proteger y nutrir no se trata de darlo todo en el momento, se trata de dar lo necesario, lo suficiente, incluso a veces con abundancia pero nunca a expensas del futuro y la seguridad. Porqué en última instancia, eres la tierra que sostiene la flor tanto en tiempos de sequía como abundancia y aunque no siempre florezca, hay que mantenerla vida. Amar tanto en los buenos, como en los malos momentos. En la abundancia, como en las dificultades.`,
  'Leo': `Los desafíos que enfrentas en tu relación de pareja son para crecer y pulir tu capacidad de amar. Las dificultades te enseñarán que si nuestras acciones no carecen de amor, también carecen de propósito y de fuerza. Entenderás que el amor es un regalo, no es algo sobre lo que tenemos control, y si lo sentimos hay que valorarlo, nutrirlo y protegerlo. Amar no es algo que podemos empezar a sentir, o dejar de hacer. Los días que inicias sintiendo pero también recibiendo amor son muy diferentes, mucho mejores a los que nos levantamos por deber, responsabilidad, necesidad o incluso deseo. Tu capacidad de amar, te hará lograr cosas que parecen impossibles, actuar con pasión, seguir tu voluntad, la determinación y atención que le dedicas a las personas o tareas que amas logran resultados admirables. También entenderás que el amor no es una fuente infinita, si no te rodeas de un entorno del que también recibas amor, tarde o temprano esa pasión, fuerza y voluntad menguara. Pero sobre todo entenderás la diferencia de hacer las cosas por amor, y hacerlas por ego. Aquello que realizes por vanidad, arrogancia o deseo de sentirte superior a otros será mucho menos efectivo e incluso dañino que cuando actúas para elevar tanto a otros como a ti misma. Entenderás que aún cuando el amor es un regalo, se te entrega para embellecer la creación de Dios, no la tuya. Con el tiempo aprenderás a distinguir entre tu voluntad y la voluntad de Dios. El amor se convertirá en tu guía para diferenciar entre ambos.`,
  'Virgo': `Las dificultades que enfrentas en tu relación de pareja son para desarrollar tu capacidad de discernimiento. Para aprender a distinguir entre el bien y el mal. Entre el orden y el caos, lo puro de lo impuro, la salud de la enfermedad y lo limpio de lo sucio. Para otras personas, incluyendo tu pareja puedes aparentar frialdad, pero a diferencia de la mayoría que al amar sienten apego, pasión o un incontrolable deseo. Tu amor está dirigido a un ideal, a un estado mental, a la tranquilidad y calma de saber que todo está bien, que todo está bajo control. Que las cosas son perfectas. Y ese ideal sólo se puede alcanzar haciendo lo correcto. A través del tiempo, la observación y de repetidas decisiones que se convierten en hábitos, alcanzarás el discernimiento de saber que es lo correcto. Y tendrás la bendición de enseñar lo correcto a las personas que amas. Tu amor no se sentirá como una caricia, o un gran gesto romántico pero con el tiempo observaras sus frutos y tus seres queridos te lo agradecerán. Tu amor se verá reflejado en la salud, en el orden, en la calma y tranquilidad de que cada día es perfecto siempre y cuando cumplamos con nuestro deber.`,
  'Libra': `Tus dificultades en pareja son para desarrollar tu sentido de la justicia. Las relaciones de pareja son complicadas y todos tendemos a creer que hacemos lo correcto y la culpa recae en la otra persona. Tu tienes el don de la indecisión, de la duda, de la inseguridad en ti misma te permiten la claridad de evaluar las situaciones, balanceando ambos puntos de vista y con frecuencia encontrando sabiamente el punto intermedio que le corresponde a cada uno. Porque para mantener una relación de pareja se necesita de las contribuciones de ambos. Pero también de buena voluntad, comunicar lo que entiendes armoniosamente y muchas veces tomando el primer paso uno mismo. Dejar atrás el resentimiento, y tomar las acciones que se requieren para asumir nuestra parte de culpa en los problemas. La única forma de dar semejante paso de desprendimiento individual, es por amor. En ocasiones ese amor se disfrazara de dependencia y apego. Está bien, siempre y cuando actúes con justicia. En el momento en que te empieces a subestimar, a minimizar todo lo que aportas a la relación, y a actuar sin dignidad, lenta o rápidamente el amor desaparecerá y la vida misma no te permitirá tomar acciones en perjuicio individual.`,
  'Escorpio': `Los desafíos que enfrentas en tu relación de pareja son para desarrollar tu capacidad de desear y atraer lo que deseas. Parece difícil de creer pero la mayoría de las personas no saben lo que desean, incluso le temen. El deseo es una de las fuerzas más poderosas de este mundo y se origina en las profundidades de nuestro interior, se esconde en nuestro subconsciente, muchas veces originados en experiencias muy tempranas de nuestra vida. Tu no solo tienes el don de saber tus deseos, sino también los de las otras personas, lo que ellos mismos no se atreven a ver. El amor te dará la fuerza que necesitas sobre todo ante las dificultades para perseguir y atraer tus deseos. En última instancia entenderás que todos los deseos se disfrazan de diferentes formas pero tienen un origen en común: PODER. Que se origina en nuestro deseo de parecernos más a Dios, nuestro creador. Lo cual no es malo, nuestra misión es buscar revelar nuestra esencia divina. Los problemas ocurren cuando el objetivo se vuelve intentar ser más poderoso que Dios, lo cual es terriblemente autodestructivo, porque en última la voluntad que prevalece siempre es la de DIOS. Por eso, ten mucho cuidado al perseguir y atraer tus deseos que estén basados en amor y no en odio o venganza. El deseo es una fuerza muy poderosa, pero no tiene moralidad, no sabe distinguir entre el bien y el mal pero al final siempre encuentra las consecuencias de sus acciones.`,
  'Sagitario': `Las dificultades que enfrentas en tu relación de pareja son para que encuentres la VERDAD. La realidad es engañosa y lo que escuchamos pueden ser mentiras, pero nuestros ojos tienen la capacidad de VER, de encontrar la verdad. Sin importar lo que otros nos digan. El don de la visión es uno que a través del amor podrás desarrollar. Amar te permitirá ver más allá de lo que otros, incluyendo tu pareja pueden ver. La verdad va más allá de lo que pasa en la vida diaria, de los rumores, de los chismes, de las mentiras. La verdad es el porqué hacemos las cosas, porque se educan a los hijos de esa forma, porque se toman esas decisiones financieras, porque te esfuerzas por lograr eso que tu pareja no entiende. La verdad no siempre es agradable, tampoco practica. Pero su búsqueda te dará algo que las personas que solo viven día a día no tienen: un propósito. Conforme te acerques a la verdad tu vida cobrará significado: el esfuerzo, las responsabilidades, las dificultades las enfrentaras con alegría. Estás aspirando a algo más grande de lo que la mayoría puede ver, y en la medida que se lo hagas entender a tu pareja y también participe las dificultades desaparecerán.`,
  'Capricornio': `Las dificultades que enfrentas en la relación de pareja son para alcanzar el HONOR. Para algunos, lo que otras personas piensen de ellos, es poco importante o superficial. Pero para ti. La opinión y admiración de otros es parte importante de tu felicidad. No me refiero a lo que tu pareja pueda pensar, sino lo que el mundo piensa sobre tu relación y tu pareja. Saber lo que es correcto no es sencillo, y aun cuando podamos estar en silencio e intentar escuchar a Dios en nuestro corazón, no siempre estaremos en lo correcto, nuestro ego nos puede engañar. Por eso la opinión de las personas es tan importante, en especial su admiración. Quizá el mundo no siempre está en lo correcto, pero si tiene la capacidad de reconocer la grandeza, lo excepcional, extraordinario y lo MEJOR. Eso es a lo que aspiras, a ser mas que otros, a tener más, a ser admirada, e incluso un poco temida. El precio será alto: trabajo, esfuerzo, responsabilidad incluso escrutinio y falta de privacidad. En tu relación de pareja, esto quiere decir que rara vez se resolverán las dificultades con entendimiento y sensibilidad. Al contrario, sera a través del trabajo y esfuerzo para alcanzar el HONOR y respetabilidad que aspiras. Es muy posible, que te toque liderar ese esfuerzo, porque depender de tu pareja solo acrecentará las dificultades.`,
  'Acuario': `Los desafíos que enfrentes en tu relación de pareja son para desarrollar tu SABIDURÍA. Desafortunadamente, la sabiduría solo se puede desarrollar a través de la experiencia. Y las dificultades que enfrentas son necesarias. Lo importante es no repetir los mismos errores. La sabiduría es tolerante con el ignorante, con quien no sabe, enseña con paciencia, amor y comprensión. Pero con quien ya sabe, y repite es inasequible, rigurosa al extremo de hacerse de que la lección quede tan grabada que no se vuelva a repetir el mismo error. Pero no te asustes, desarrollar sabiduría es también muy gratificante. Primero, porque en lugar de escuchar las opiniones, y consejos de otros, desarrollarás tu individualidad. Quien no escucha a otros porque sabe, el tiempo eventualmente le dará la razón, y será admirado por su sabiduría. Además de desarrollar tu individualidad, la sabiduría te concede uno de los regalos más preciados en esta vida: la LIBERTAD. Entenderás que la gran mayoría de las personas no es libre está atada a sus emociones, parejas, responsabilidades, juicios o limitations. Pero cuando aprendas a conocer las reglas del juego sabrás como ser emocional sin apegos, amar sin dependencias, juzgar sin prejuicios y explorar caminos que pocos se atreven pero pueden ser correctos. Agradece a tu pareja, aún es sus fallas, y escucha el amor que sientes porque el amor te guiará a la sabiduría evitando muchos de los errores.`,
  'Piscis': `Las dificultades que enfrentas en tu relación de pareja son para desarrollar tu espiritualidad y que encuentres la FE. El amor te hará entender que la realidad que vivimos en este mundo material, es infinitamente menos importante, menos real que el mundo espiritual al que tenemos acceso cuando encontramos y aceptamos a Dios en nuestro corazón. La fe te hará desbordar un amor tan grande que trasciende la razón. Un amor tan inmenso que es capaz de perdonar. Un amor tan expansivo que incluso podrá ser no tolerado por otras personas. Tendrá tanto poder, tanta fuerza que infundirá compasión hasta en la más material de las personas. Las dificultades te harán entender, que la razón por la que existe tanto sufrimiento y tanta tristeza en este mundo es porque nuestra capacidad de amor es tan limitada. Tu capacidad de amor se convertirá en esa antorcha que ilumine hasta el más gris de los días. Y cuando las personas se pregunten cómo eres capaz de dar tanto, sin esperar nada a cambio. Cómo eres capaz de perdonar sin guardar rencor. Y como obsequias compasión, y misericordia a quien menos lo merece, o atención recibe. Tú sabrás que detrás de tanto está tu FE, porque el amor te obsequia el don de escuchar a DIOS directamente en tu corazón. Y quien es testigo de su grandeza, de su poder, entrega su vida con absoluta devoción. Que así sea.`
};

export function getLectureForScript(scriptId: string, user: UserProfile | null) {
  if (!user) return null;

  switch (scriptId) {
    case 'identidad':
      return {
        title: `Tu Sol en ${user.sunSign}`,
        content: SUN_LECTURES[user.sunSign] || 'No se encontró lectura para tu signo solar.'
      };
    case 'emociones':
      return {
        title: `Tu Luna en ${user.moonSign}`,
        content: MOON_LECTURES[user.moonSign] || 'No se encontró lectura para tu signo lunar.'
      };
    case 'venus':
      return {
        title: `Tu Venus en ${user.venusSign}`,
        content: VENUS_LECTURES[user.venusSign] || 'No se encontró lectura para tu signo de Venus.'
      };
    case 'casa_solar':
      return {
        title: `Tu Casa Solar en ${user.casaSolar || ''}`,
        content: user.casaSolar ? (CASA_SOLAR_LECTURES[user.casaSolar] || 'No se encontró lectura para tu Casa Solar.') : 'No se configuró Casa Solar.'
      };
    case 'casa_karma':
      return {
        title: `Tu Casa del Karma en ${user.casaKarma || ''}`,
        content: user.casaKarma ? (CASA_KARMA_LECTURES[user.casaKarma] || 'No se encontró lectura para tu Casa del Karma.') : 'No se configuró Casa del Karma.'
      };
    case 'valores': {
      const signLect = VALORES_LECTURES[user.venusSign] || 'No se encontró lectura para tus Valores.';
      return {
        title: `Tus Valores en ${user.venusSign}`,
        content: `${VALORES_INTRO_LECTURE}\n\n${signLect}`
      };
    }
    default:
      return null;
  }
}
